param([Parameter(Mandatory)][ValidateSet('Gateway','Ngrok','Cloudflare')][string]$Entry,[string]$InstallRoot="$env:ProgramData\Aevrynd\LineGateway",[string]$ConfigPath='',[switch]$Wait)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
if(-not('AevryndBootstrapNative'-as[type])){Add-Type @'
using System;using System.ComponentModel;using System.Runtime.InteropServices;using System.Text;using Microsoft.Win32.SafeHandles;
public static class AevryndBootstrapNative{[DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetFinalPathNameByHandle(SafeFileHandle h,StringBuilder b,uint n,uint f);public static string FinalPath(SafeFileHandle h){var b=new StringBuilder(32768);uint n=GetFinalPathNameByHandle(h,b,(uint)b.Capacity,0);if(n==0||n>=b.Capacity)throw new Win32Exception(Marshal.GetLastWin32Error());string p=b.ToString();return p.StartsWith(@"\\?\")?p.Substring(4):p;}}
'@}
function Assert-ProtectedDirectory([string]$Path){$item=Get-Item -LiteralPath $Path -Force;if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw 'Bootstrap trust directory is invalid.'};$acl=Get-Acl -LiteralPath $Path;if(-not$acl.AreAccessRulesProtected){throw 'Bootstrap trust directory inherits mutable ACLs.'};$mutation=[Security.AccessControl.FileSystemRights]::WriteData-bor[Security.AccessControl.FileSystemRights]::AppendData-bor[Security.AccessControl.FileSystemRights]::WriteExtendedAttributes-bor[Security.AccessControl.FileSystemRights]::WriteAttributes-bor[Security.AccessControl.FileSystemRights]::Delete-bor[Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles-bor[Security.AccessControl.FileSystemRights]::ChangePermissions-bor[Security.AccessControl.FileSystemRights]::TakeOwnership;foreach($rule in $acl.Access){if($rule.AccessControlType-ne'Deny'-and($rule.FileSystemRights-band$mutation)-and$rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value-notin@('S-1-5-18','S-1-5-32-544')){throw 'Bootstrap trust directory grants mutation rights outside SYSTEM and Administrators.'}}}
function Open-FixedFile([string]$Path,[int]$Limit){$full=[IO.Path]::GetFullPath($Path);$stream=[IO.FileStream]::new($full,'Open','Read','Read');try{if([AevryndBootstrapNative]::FinalPath($stream.SafeFileHandle)-cne$full-or$stream.Length-lt1-or$stream.Length-gt$Limit){throw 'Bootstrap file identity or size is invalid.'};return $stream}catch{$stream.Dispose();throw}}
function Read-HeldBytes([IO.FileStream]$Stream){$Stream.Position=0;$bytes=[byte[]]::new([int]$Stream.Length);$offset=0;while($offset-lt$bytes.Length){$n=$Stream.Read($bytes,$offset,$bytes.Length-$offset);if($n-eq0){throw 'Bootstrap file was truncated.'};$offset+=$n};if($Stream.ReadByte()-ne-1){throw 'Bootstrap file changed during read.'};return $bytes}
$root=[IO.Path]::GetFullPath($InstallRoot).TrimEnd('\');$scripts=Join-Path $root 'scripts';$manifests=Join-Path $root 'manifests';Assert-ProtectedDirectory $root;Assert-ProtectedDirectory $scripts;Assert-ProtectedDirectory $manifests
$self=[IO.Path]::GetFullPath($PSCommandPath);if(-not$self.StartsWith($scripts.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Bootstrap is outside the protected scripts directory.'};$selfHandle=Open-FixedFile $self 1048576;$manifestHandle=$null;$hashHandle=$null;$targetHandle=$null;$manifestBytes=$null;$hashBytes=$null
try{$manifestHandle=Open-FixedFile (Join-Path $manifests 'installation-manifest.json') 1048576;$hashHandle=Open-FixedFile (Join-Path $manifests 'installation-manifest.sha256') 256;$manifestBytes=Read-HeldBytes $manifestHandle;$hashBytes=Read-HeldBytes $hashHandle;$expected=[Text.UTF8Encoding]::new($false,$true).GetString($hashBytes).Trim().ToLowerInvariant();$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[Convert]::ToHexString($sha.ComputeHash($manifestBytes)).ToLowerInvariant()}finally{$sha.Dispose()};if($expected-notmatch'^[0-9a-f]{64}$'-or$actual-cne$expected){throw 'Bootstrap manifest digest is invalid.'};$manifest=[Text.UTF8Encoding]::new($false,$true).GetString($manifestBytes)|ConvertFrom-Json;$selfEntries=@($manifest.files|Where-Object{([string]$_.path).Replace('/','\')-ceq'scripts\Bootstrap.ps1'});if($selfEntries.Count-ne1){throw 'Bootstrap is absent from the closed manifest.'};$selfBytes=Read-HeldBytes $selfHandle;try{$sha=[Security.Cryptography.SHA256]::Create();try{$selfDigest=[Convert]::ToHexString($sha.ComputeHash($selfBytes)).ToLowerInvariant()}finally{$sha.Dispose()};if($selfHandle.Length-ne[long]$selfEntries[0].size-or$selfDigest-cne[string]$selfEntries[0].sha256){throw 'Bootstrap self identity differs from manifest.'}}finally{[Array]::Clear($selfBytes,0,$selfBytes.Length)}
 $name=@{Gateway='Start-Gateway.ps1';Ngrok='Start-Ngrok.ps1';Cloudflare='Start-Tunnel.ps1'}[$Entry];$relative="scripts\$name";$entries=@($manifest.files|Where-Object{([string]$_.path).Replace('/','\')-ceq$relative});if($entries.Count-ne1-or[string]$entries[0].sha256-notmatch'^[0-9a-f]{64}$'){throw 'Bootstrap target is absent from the closed manifest.'};$target=[IO.Path]::GetFullPath((Join-Path $root $relative));$targetHandle=Open-FixedFile $target 4194304;if($targetHandle.Length-ne[long]$entries[0].size){throw 'Bootstrap target size differs from manifest.'};$targetBytes=Read-HeldBytes $targetHandle;try{$sha=[Security.Cryptography.SHA256]::Create();try{$digest=[Convert]::ToHexString($sha.ComputeHash($targetBytes)).ToLowerInvariant()}finally{$sha.Dispose()};if($digest-cne[string]$entries[0].sha256){throw 'Bootstrap target hash differs from manifest.'}}finally{[Array]::Clear($targetBytes,0,$targetBytes.Length)}
 switch($Entry){'Gateway'{& $target -InstallRoot $InstallRoot -Wait:$Wait}'Ngrok'{& $target -InstallRoot $InstallRoot}'Cloudflare'{if([string]::IsNullOrWhiteSpace($ConfigPath)){throw 'Cloudflare bootstrap requires ConfigPath.'};& $target -ConfigPath $ConfigPath}}
}finally{if($null-ne$manifestBytes){[Array]::Clear($manifestBytes,0,$manifestBytes.Length)};if($null-ne$hashBytes){[Array]::Clear($hashBytes,0,$hashBytes.Length)};foreach($handle in @($targetHandle,$hashHandle,$manifestHandle,$selfHandle)){if($null-ne$handle){$handle.Dispose()}}}
